css:
.en-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.en-stage canvas { touch-action: none; cursor: grab; }
.en-stage canvas.holding { cursor: grabbing; }
.en-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.en-table { width: 100%; border-collapse: collapse; font-size: 18px; }
.en-table th, .en-table td { border: 1.5px solid var(--rule); padding: 3px 8px; text-align: left; }
.en-table thead th { background: #eef2f7; }

